54:         static float Approach(float v,float target,float step) { return v < target ? Math.Min(v+step,target) : Math.Max(v-step,target); }
55:         public void Damage(Fighter source, Fighter target, float amount, bool physical,bool applyMark=true)
56:         {
57:             if(target.hp<=0||amount<=0)return;
58:             float dealt = amount * 100f / (100f + (physical ? target.armor : target.mr));
59:             if(target.barrierUntil>time&&target.barrier>0){float absorbed=Math.Min(target.barrier,dealt);target.barrier-=absorbed;dealt-=absorbed;}
60:             if(!physical && target.Shielded(time)) { float absorbed = Math.Min(target.shield,dealt); target.shield -= absorbed; dealt -= absorbed; }
61:             target.hp = Math.Max(0,target.hp-dealt);
62:             if(source.champion == "Morgana"&&source.hp>0) source.hp = Math.Min(source.maxHp,source.hp+dealt*0.18f);
63:             if(source.champion == "Ezreal") source.stacks = Math.Min(5,source.stacks+1);
64:             if(source.champion=="Mel"&&applyMark&&dealt>0&&target.champion!="Turret")
65:             {
66:                 if(!target.MarkedBy(source,time))target.overwhelm=0;
67:                 if(target.overwhelm<int.MaxValue)target.overwhelm++;
68:                 target.overwhelmOwner=source;target.overwhelmUntil=time+5;
69:                 if(target.hp>0&&target.hp<40+.1f*source.ap+target.overwhelm*6){target.hp=0;target.overwhelm=0;Log("Overwhelm executes "+target.champion);}
70:             }
71:         }
