99:         public bool BeginCast(Fighter source,Fighter target,int slot)
100:         {
101:             if(slot<0 || slot>3 || source.hp<=0 || time<source.ready[slot]||source.mana<ChampionKit.Mana(source.champion,slot)) return false;
102:             if(source.champion=="Mel"&&slot==3&&!target.MarkedBy(source,time)){Log("Golden Eclipse needs an active Overwhelm mark");return false;}
103:             if(source.ActiveControl(time) && (source.control=="Stun" || source.control=="Charm")) { Log("Cast blocked by "+source.control); return false; }
104:             bool move=(source.champion=="Ezreal"&&slot==2)||(source.champion=="Ahri"&&slot==3);
105:             if(move&&!Mobility(source)) { Log("Mobility blocked by "+source.control); return false; }
106:             source.mana-=ChampionKit.Mana(source.champion,slot);
107:             source.ready[slot]=time+ChampionKit.Cooldown(source.champion,slot)/(1+source.haste/100);
108:             if(source.champion=="Ahri"&&slot==3&&source.rushCharges<=0) source.rushCharges=3;
109:             if(source.champion=="Mel")source.searing=Math.Min(9,source.searing+3);
110:             Log(source.champion+" casts "+Names(source.champion)[slot]);
111:             return true;
112:         }
